package org.apache.commons.cli;

import java.io.*;
import java.io.PrintWriter;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.Iterator;
import java.util.List;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class HelpFormatter_renderWrappedText_TriageGen2Test {

    @Test
    public void testRenderWrappedText_NoWrap() {
        HelpFormatter formatter = new HelpFormatter();
        StringBuffer sb = new StringBuffer();
        int width = 10;
        int nextLineTabStop = 4;
        String text = "HelloWorld";
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals(text, sb.toString());
    }

    @Test
    public void testRenderWrappedText_OneWrap() {
        HelpFormatter formatter = new HelpFormatter();
        StringBuffer sb = new StringBuffer();
        int width = 10;
        int nextLineTabStop = 4;
        String text = "This is a very very very very very very very very very very very long text";
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals("This is a very very very very very very \n          very very very very very very very \n          very very very very very very very \n          very very very very very very very very very very very long text", sb.toString());
    }

    @Test
    public void testRenderWrappedText_MultipleWraps() {
        HelpFormatter formatter = new HelpFormatter();
        StringBuffer sb = new StringBuffer();
        int width = 10;
        int nextLineTabStop = 4;
        String text = "This is a very very very very very very very very very very very long text that needs to be wrapped multiple times";
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals("This is a very very very very very very \n          very very very very very very very \n          very very very very very very very \n          very very very very very very very very very very very long text that needs \n          to be wrapped multiple times", sb.toString());
    }

    @Test
    public void testRenderWrappedText_EmptyText() {
        HelpFormatter formatter = new HelpFormatter();
        StringBuffer sb = new StringBuffer();
        int width = 10;
        int nextLineTabStop = 4;
        String text = "";
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals("", sb.toString());
    }

    @Test
    public void testRenderWrappedText_NullText() {
        HelpFormatter formatter = new HelpFormatter();
        StringBuffer sb = new StringBuffer();
        int width = 10;
        int nextLineTabStop = 4;
        String text = null;
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals("", sb.toString());
    }
}
